SOURCES = {'nthllm/__init__.py': "LABELS = (\n    'gpt-5.5', 'gpt-5.6-luna', 'gpt-5.6-sol', 'gpt-5.6-terra', 'gpt-6-astra',\n    'gemini-3.1-pro-preview', 'gemini-3.6-flash', 'gemini-3.7-flash',\n    'gemini-3.8-flash', 'claude-fable-5', 'claude-opus-4-6', 'claude-opus-4-8',\n    'claude-opus-5', 'claude-sonnet-5', 'qwen3.8-max', 'glm-5.3',\n    'glm-5.3-flash', 'kimi-k3',\n)\n", 'nthllm/features.py': 'import math\nimport re\nimport warnings\nimport zlib\nfrom collections import Counter\nfrom pathlib import Path\n\nimport numpy as np\nfrom sklearn.base import BaseEstimator, TransformerMixin\n\n\nFUNCTION_WORDS = \'the a an and or but if while although because to of in on for with by from is are was were be it this that we you\'.split()\n# A fixed reference vocabulary avoids fitting frequency statistics across CV folds.\nREFERENCE = (\'the of and to a in is it you that he was for on are as with his they at \'\n             \'be this have from or one had by word but not what all were we when your \'\n             \'can said there use an each which she do how their if will up other about \'\n             \'out many then them these so some her would make like time has look two \'\n             \'more write go see number no way could people my than first water been \'\n             \'call who oil its now find long down day did get come made may part\').split()\nRANK = {word: i + 1 for i, word in enumerate(REFERENCE)}\n\n\nclass StyleFeatures(BaseEstimator, TransformerMixin):\n    def fit(self, X, y=None):\n        return self\n\n    def transform(self, X):\n        rows = [self._row(str(text)) for text in X]\n        return np.asarray(rows, dtype=np.float64).reshape(-1, len(self.get_feature_names_out()))\n\n    def get_feature_names_out(self, input_features=None):\n        return np.array(self._row(\'\', names=True))\n\n    @staticmethod\n    def _row(text, names=False):\n        words = re.findall(r"\\b[\\w]+(?:[\'’][\\w]+)?\\b", text.lower())\n        sentences = [s.strip() for s in re.split(r\'[.!?]+\', text) if s.strip()]\n        n, c = max(len(words), 1), max(len(text), 1)\n        lengths = [len(w) for w in words] or [0]\n        sl = [len(s.split()) for s in sentences] or [0]\n        counts = Counter(text)\n        f = dict(word_count=len(words), ttr=len(set(words))/n,\n                 word_length_mean=np.mean(lengths), word_length_std=np.std(lengths),\n                 sentence_length_mean=np.mean(sl), sentence_length_std=np.std(sl),\n                 sentence_count=len(sentences), long_word_rate=sum(x > 7 for x in lengths)/n,\n                 entropy=-sum((v/c)*math.log2(v/c) for v in counts.values()),\n                 compression=len(zlib.compress(text.encode()))/max(len(text.encode()), 1),\n                 mean_rank=np.mean([RANK.get(w, 1000) for w in words] or [0]),\n                 rare_rate=sum(w not in RANK for w in words)/n,\n                 uppercase=sum(ch.isupper() for ch in text)/c,\n                 digit_rate=sum(ch.isdigit() for ch in text)/c)\n        for word in FUNCTION_WORDS:\n            f[\'fw_\' + word] = words.count(word)/n\n        for key, pattern in {\n            \'em_dash\':\'—\', \'en_dash\':\'–\', \'semicolon\':\';\', \'colon\':\':\',\n            \'curly_quotes\':\'[“”‘’]\', \'straight_quotes\':\'[\\"\\\']\',\n            \'parentheses\':r\'[()]\', \'ellipsis\':r\'\\.\\.\\.|…\', \'bold\':r\'\\*\\*\',\n            \'heading\':r\'(?m)^\\s*#+ \', \'bullet\':r\'(?m)^\\s*- \',\n            \'numbered\':r\'(?m)^\\s*\\d+[.)] \', \'newline\':r\'\\n\',\n            \'comma\':\',\', \'question\':r\'\\?\', \'exclamation\':\'!\',\n            \'contraction\':r"\\b\\w+[\'’](?:t|s|re|ve|ll|d)\\b",\n            \'passive_proxy\':r\'\\b(?:is|was|were|been|be)\\s+\\w+ed\\b\',\n            \'adverb_proxy\':r\'\\b\\w+ly\\b\',\n        }.items():\n            f[key] = len(re.findall(pattern, text))/c\n        for start in (\'however\', \'the\', \'in\', \'we\', \'this\', \'first\', \'although\'):\n            f[\'starts_\' + start] = sum(bool(re.match(start + r\'\\b\', s.lower())) for s in sentences)/max(len(sentences), 1)\n        return list(f) if names else list(f.values())\n\n\nclass LocalPerplexity(BaseEstimator, TransformerMixin):\n    """Optional offline causal-LM feature; missing dependencies yield a zero column."""\n\n    def __init__(self, model_path=None, max_tokens=256):\n        self.model_path = model_path\n        self.max_tokens = max_tokens\n\n    def fit(self, X, y=None):\n        return self\n\n    def transform(self, X):\n        texts = list(X)\n        result = np.zeros((len(texts), 1))\n        if not self.model_path:\n            return result\n        try:\n            if not Path(self.model_path).is_dir():\n                raise FileNotFoundError(self.model_path)\n            import torch\n            from transformers import AutoModelForCausalLM, AutoTokenizer\n            tokenizer = AutoTokenizer.from_pretrained(self.model_path, local_files_only=True)\n            model = AutoModelForCausalLM.from_pretrained(self.model_path, local_files_only=True).eval()\n            for i, text in enumerate(texts):\n                tokens = tokenizer(text, return_tensors=\'pt\', truncation=True, max_length=self.max_tokens)\n                if tokens[\'input_ids\'].shape[1] > 1:\n                    with torch.no_grad():\n                        loss = model(**tokens, labels=tokens[\'input_ids\']).loss.item()\n                    result[i, 0] = math.exp(min(loss, 20)) if math.isfinite(loss) else 0\n        except (ImportError, OSError, ValueError, RuntimeError) as exc:\n            warnings.warn(f\'Local perplexity unavailable; using zeros: {exc}\', RuntimeWarning)\n        return result\n', 'nthllm/modeling.py': "import time\n\nimport numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression, SGDClassifier\nfrom sklearn.metrics import balanced_accuracy_score, recall_score\nfrom sklearn.model_selection import GroupKFold\nfrom sklearn.pipeline import FeatureUnion, Pipeline\nfrom sklearn.preprocessing import MaxAbsScaler\nfrom sklearn.svm import LinearSVC\n\nfrom nthllm import LABELS\nfrom nthllm.features import LocalPerplexity, StyleFeatures\n\n\ndef make_features(lm_path=None):\n    return FeatureUnion([\n        ('char', TfidfVectorizer(analyzer='char_wb', ngram_range=(1, 5),\n                                sublinear_tf=True, max_features=35000)),\n        ('word', TfidfVectorizer(ngram_range=(1, 2), sublinear_tf=True,\n                                max_features=18000, token_pattern=r'(?u)\\b\\w+\\b')),\n        ('style', Pipeline([('extract', StyleFeatures()), ('scale', MaxAbsScaler())])),\n        ('lm', Pipeline([('extract', LocalPerplexity(lm_path)), ('scale', MaxAbsScaler())])),\n    ])\n\n\ndef make_models():\n    return {\n        'logistic': LogisticRegression(C=4, class_weight='balanced', max_iter=600),\n        # Calibration is fitted inside each outer training fold, never on held-out prompts.\n        'calibrated_svc': CalibratedClassifierCV(\n            LinearSVC(C=0.7, class_weight='balanced', dual='auto'), method='sigmoid'),\n        'sgd': SGDClassifier(loss='log_loss', alpha=0.001, class_weight='balanced',\n                             max_iter=1000, tol=1e-4, random_state=42),\n    }\n\n\ndef probabilities(models, X):\n    result = {}\n    for name, model in models.items():\n        aligned = np.zeros((X.shape[0], len(LABELS)))\n        raw = model.predict_proba(X)\n        for column, label in enumerate(model.classes_):\n            aligned[:, LABELS.index(label)] = raw[:, column]\n        result[name] = aligned\n    result['ensemble'] = np.mean(list(result.values()), axis=0)\n    return result\n\n\ndef train(data, folds=5, lm_path=None):\n    required = {'id', 'prompt_id', 'text', 'model'}\n    if not required.issubset(data.columns) or data[list(required)].isna().any().any():\n        raise ValueError('Training data requires non-null id, prompt_id, text, model')\n    if set(data.model) != set(LABELS):\n        raise ValueError('Training data must contain exactly the 18 competition labels')\n    if data.id.duplicated().any():\n        raise ValueError('Duplicate training IDs')\n    start = time.perf_counter()\n    scores = {name: [] for name in [*make_models(), 'ensemble']}\n    oof = {name: np.empty(len(data), dtype=object) for name in scores}\n    split_report = []\n    for fold, (tr, va) in enumerate(GroupKFold(folds).split(data, data.model, data.prompt_id), 1):\n        if set(data.iloc[tr].model) != set(LABELS):\n            raise ValueError('Every training fold must contain all labels; use more prompts')\n        features = make_features(lm_path)\n        X = features.fit_transform(data.iloc[tr].text)\n        V = features.transform(data.iloc[va].text)\n        models = make_models()\n        # Inner calibration also respects prompt groups.\n        inner = list(GroupKFold(3).split(X, data.iloc[tr].model, data.iloc[tr].prompt_id))\n        models['calibrated_svc'].cv = inner\n        for model in models.values():\n            model.fit(X, data.iloc[tr].model)\n        for name, probs in probabilities(models, V).items():\n            pred = np.array(LABELS)[probs.argmax(axis=1)]\n            oof[name][va] = pred\n            score = balanced_accuracy_score(data.iloc[va].model, pred)\n            scores[name].append(float(score))\n            print(f'fold={fold} {name}: {score:.4f}', flush=True)\n        split_report.append({'fold': fold, 'train_prompts': sorted(map(str, data.iloc[tr].prompt_id.unique())),\n                             'valid_prompts': sorted(map(str, data.iloc[va].prompt_id.unique()))})\n    report = {'models': {}, 'splits': split_report}\n    for name, values in scores.items():\n        report['models'][name] = {'fold_scores': values, 'mean': float(np.mean(values)),\n                                  'std': float(np.std(values)), 'per_class_recall': dict(zip(\n                                      LABELS, recall_score(data.model, oof[name], labels=LABELS,\n                                                           average=None, zero_division=0).tolist()))}\n    features = make_features(lm_path)\n    X = features.fit_transform(data.text)\n    models = make_models()\n    models['calibrated_svc'].cv = list(GroupKFold(3).split(X, data.model, data.prompt_id))\n    for model in models.values():\n        model.fit(X, data.model)\n    report['runtime_seconds'] = time.perf_counter() - start\n    return {'features': features, 'models': models, 'labels': LABELS}, report\n\n\ndef predict(artifact, texts):\n    X = artifact['features'].transform(texts)\n    return np.array(LABELS)[probabilities(artifact['models'], X)['ensemble'].argmax(axis=1)]\n", 'nthllm/submission.py': "import pandas as pd\n\nfrom nthllm import LABELS\n\n\ndef validate_submission(submission, test):\n    if list(submission.columns) != ['id', 'model']:\n        raise ValueError('Submission columns must be id, model in that order')\n    if submission.isna().any().any() or test.id.isna().any():\n        raise ValueError('Null submission values or test IDs')\n    if submission.id.duplicated().any() or test.id.duplicated().any():\n        raise ValueError('Duplicate IDs')\n    if len(submission) != len(test) or set(submission.id) != set(test.id):\n        raise ValueError('Submission IDs must match test exactly')\n    if not submission.model.isin(LABELS).all():\n        raise ValueError('Invalid model labels')\n    return submission\n\n\ndef write_submission(test, predictions, out, csv=None):\n    submission = validate_submission(pd.DataFrame({'id': test.id, 'model': predictions}), test)\n    submission.to_parquet(out, index=False)\n    if csv:\n        submission.to_csv(csv, index=False)\n    return submission\n"}

bundle = Path(tempfile.mkdtemp(prefix='nthllm-offline-'))
for name, source in SOURCES.items():
    target = bundle / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(source)
sys.path.insert(0, str(bundle))

import pandas as pd
from nthllm.modeling import make_features, make_models, predict
from nthllm.submission import write_submission
from sklearn.model_selection import GroupKFold

def main():
    data_dir = Path(os.environ.get('NTHLLM_DATA_DIR', '/kaggle/input/competitions/name-that-llm'))
    train = pd.read_csv(data_dir / 'train.csv')
    test = pd.read_csv(data_dir / 'test.csv')
    features = make_features(os.environ.get('NTHLLM_LM_PATH'))
    X = features.fit_transform(train.text)
    models = make_models()
    models['calibrated_svc'].cv = list(GroupKFold(3).split(X, train.model, train.prompt_id))
    for model in models.values():
        model.fit(X, train.model)
    artifact = {'features': features, 'models': models}
    out = os.environ.get('NTHLLM_OUT', 'submission.parquet')
    write_submission(test, predict(artifact, test.text), out)
    print(f'Offline notebook: validated {len(test)} rows -> {out}')

if __name__ == '__main__':
    main()
